/**
 * Exporta renglones de `accesos` (tal como los regresa GET /api/accesos,
 * incluyendo firma_entrada/firma_salida en base64) a un PDF con las firmas
 * digitales embebidas como imagen.
 *
 * El PDF se dibuja como una tabla (encabezado gris + rejilla), replicando
 * el formato oficial en papel de la Cintoteca ("6. Formato de Bitácora de
 * Acceso": No. / Nombre / Hora de entrada / Hora de salida / Puesto o
 * cargo / Motivo de acceso / Firma — se omite "Número de elementos
 * manipulados" porque este sistema no captura ese dato), con el mismo
 * membrete e identidad de color (azul CNS/IPICYT) que usan los demás
 * documentos formales de la institución (p. ej. las hojas de resguardo de
 * equipo).
 *
 * Usa jsPDF cargado desde CDN en index.html como `window.jspdf.jsPDF` — no
 * es un import de módulo porque este proyecto no tiene paso de bundling
 * para dependencias de npm en el frontend (ver <script> en index.html).
 */

const MARGEN = 40;

// Logo CNS embebido como base64 (mismo archivo que src/assets/logo-cns.webp,
// reescalado a PNG) para que el PDF sea un archivo autocontenido y no
// dependa de cargar una imagen externa al momento de generarlo.
const LOGO_CNS_PNG = 'data:image/png;base64,';
const LOGO_ANCHO_PT = 108;
const LOGO_ALTO_PT = 38.6; // mismo aspect ratio que el PNG fuente (260x93)

// Identidad de color CNS/IPICYT usada en el membrete y en el encabezado de
// la tabla (tomado del azul del logotipo).
const AZUL_CNS = [47, 63, 137];
const AZUL_CNS_OSCURO = [15, 26, 66];

const MESES_ABREV = ['Ene.', 'Feb.', 'Mar.', 'Abr.', 'May.', 'Jun.', 'Jul.', 'Ago.', 'Sep.', 'Oct.', 'Nov.', 'Dic.'];

// Columnas de la tabla: igual al formato en papel, sin "Número de
// elementos manipulados". Los anchos suman el ancho útil de una hoja
// carta (612pt - 2*40pt de margen = 532pt).
const COLUMNAS = [
  { key: 'no', label: 'No.', width: 26, align: 'center' },
  { key: 'nombre', label: 'Nombre de la persona que ingresa', width: 118, align: 'left' },
  { key: 'horaEntrada', label: 'Hora de entrada', width: 55, align: 'center' },
  { key: 'horaSalida', label: 'Hora de salida', width: 55, align: 'center' },
  { key: 'puesto', label: 'Puesto o cargo', width: 88, align: 'left' },
  { key: 'motivo', label: 'Motivo de acceso', width: 90, align: 'left' },
  { key: 'firma', label: 'Firma', width: 100, align: 'center' }
];

const ALTO_ENCABEZADO = 30;
const ALTO_MIN_FILA = 40;
const PAD_X = 4;
const PAD_Y = 5;
const ALTO_LINEA_TEXTO = 9;
const ANCHO_FIRMA_MINI = 42;
const ALTO_FIRMA_MINI = 20;

function agruparPorFolio(rows) {
  const orden = [];
  const grupos = new Map();
  rows.forEach(row => {
    if (!grupos.has(row.folio_grupo)) {
      grupos.set(row.folio_grupo, {
        folio_grupo: row.folio_grupo,
        motivo: row.motivo,
        acompanante: row.acompanante || null,
        fecha: row.fecha,
        personas: []
      });
      orden.push(row.folio_grupo);
    }
    grupos.get(row.folio_grupo).personas.push(row);
  });
  return orden.map(f => grupos.get(f));
}

function formatFechaLarga(fecha) {
  return `${MESES_ABREV[fecha.getMonth()]} ${fecha.getDate()}, ${fecha.getFullYear()}`;
}

/**
 * Aplana los grupos por folio a un renglón de tabla por persona, listo
 * para dibujar. El motivo de acceso se repite por persona (así queda
 * igual que si cada quien firmara su propio renglón en la hoja de papel),
 * y si el folio tiene un acompañante registrado se anota una sola vez, en
 * el primer renglón del folio.
 */
function aplanarFilas(grupos) {
  const filas = [];
  grupos.forEach(grupo => {
    grupo.personas.forEach((persona, idx) => {
      filas.push({
        no: grupo.folio_grupo,
        nombre: persona.nombre || '—',
        horaEntrada: persona.hora_entrada ? String(persona.hora_entrada).slice(0, 5) : '—',
        horaSalida: persona.hora_salida ? String(persona.hora_salida).slice(0, 5) : '— (aún dentro)',
        puesto: persona.puesto || '—',
        motivo: idx === 0 && grupo.acompanante
          ? `${grupo.motivo || '—'}  (Acompañado por: ${grupo.acompanante})`
          : (grupo.motivo || '—'),
        firmaEntrada: persona.firma_entrada || null,
        firmaSalida: persona.firma_salida || null
      });
    });
  });
  return filas;
}

/**
 * @param {Array} rows           Filas de accesos (una por persona).
 * @param {Object} opciones
 * @param {string} opciones.titulo
 * @param {string} opciones.subtitulo
 */
export function exportarAccesosPDF(rows, { titulo = 'Bitácora de Acceso a Cintoteca', subtitulo = '' } = {}) {
  if (!window.jspdf || !window.jspdf.jsPDF) {
    console.error('jsPDF no está disponible (revisa el <script> de jspdf en index.html).');
    return;
  }
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'pt', format: 'letter' });
  const anchoPagina = doc.internal.pageSize.getWidth();
  const altoPagina = doc.internal.pageSize.getHeight();
  const anchoTabla = COLUMNAS.reduce((sum, c) => sum + c.width, 0);
  const xDerecha = anchoPagina - MARGEN;

  // Posición x de cada columna, acumulada desde el margen izquierdo.
  let xAcum = MARGEN;
  const columnasX = COLUMNAS.map(c => {
    const x = xAcum;
    xAcum += c.width;
    return x;
  });

  let y = MARGEN;

  function dibujarEncabezadoDocumento() {
    // ---- Membrete: logo CNS a la izquierda + nombre del instituto ----
    try {
      doc.addImage(LOGO_CNS_PNG, 'PNG', MARGEN, y, LOGO_ANCHO_PT, LOGO_ALTO_PT, undefined, 'FAST');
    } catch { /* si el logo no carga, el membrete sigue con solo texto */ }

    const xTexto = MARGEN + LOGO_ANCHO_PT + 16;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10.5);
    doc.setTextColor(0);
    // Envuelto explícitamente (en vez de maxWidth automático) para saber
    // con certeza cuántas líneas ocupó y no encimar lo que sigue.
    const lineasNombre = doc.splitTextToSize(
      'INSTITUTO POTOSINO DE INVESTIGACIÓN CIENTÍFICA Y TECNOLÓGICA A.C.',
      xDerecha - xTexto
    );
    let yNombre = y + 13;
    lineasNombre.forEach(linea => {
      doc.text(linea, xTexto, yNombre);
      yNombre += 12;
    });
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(...AZUL_CNS);
    doc.text('CINTOTECA · SAN LUIS POTOSÍ, MÉX.', xTexto, yNombre + 2);
    doc.setTextColor(0);
    yNombre += 16;

    y = Math.max(y + LOGO_ALTO_PT, yNombre) + 20;

    // ---- Título centrado ----
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(13);
    doc.setTextColor(...AZUL_CNS_OSCURO);
    doc.text(titulo.toUpperCase(), anchoPagina / 2, y, { align: 'center' });
    doc.setTextColor(0);
    y += 20;

    // ---- Lugar/fecha y periodo exportado, alineados a la derecha ----
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(90);
    doc.text(`San Luis Potosí, S.L.P. ${formatFechaLarga(new Date())}`, xDerecha, y, { align: 'right' });
    y += 14;
    if (subtitulo) {
      doc.text(subtitulo, xDerecha, y, { align: 'right' });
      y += 13;
    }
    doc.setFontSize(7.5);
    doc.setTextColor(130);
    doc.text(`Exportado: ${new Date().toLocaleString('es-MX')}`, xDerecha, y, { align: 'right' });
    doc.setTextColor(0);
    y += 14;

    doc.setDrawColor(...AZUL_CNS);
    doc.setLineWidth(1.4);
    doc.line(MARGEN, y, xDerecha, y);
    doc.setLineWidth(0.5);
    y += 18;
  }

  function dibujarEncabezadoTabla() {
    doc.setDrawColor(255);
    doc.setLineWidth(0.75);
    doc.setFillColor(...AZUL_CNS);
    doc.rect(MARGEN, y, anchoTabla, ALTO_ENCABEZADO, 'F');

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(7.5);
    doc.setTextColor(255, 255, 255);
    COLUMNAS.forEach((col, i) => {
      const x = columnasX[i];
      const lineas = doc.splitTextToSize(col.label, col.width - PAD_X * 2);
      const altoBloque = lineas.length * ALTO_LINEA_TEXTO;
      let ly = y + (ALTO_ENCABEZADO - altoBloque) / 2 + ALTO_LINEA_TEXTO - 2;
      lineas.forEach(linea => {
        dibujarTextoAlineado(linea, x, ly, col.width, col.align);
        ly += ALTO_LINEA_TEXTO;
      });
      // Divisores delgados en blanco, sutiles sobre el azul del encabezado.
      if (i > 0) doc.line(x, y, x, y + ALTO_ENCABEZADO);
    });
    doc.setTextColor(0);
    doc.setDrawColor(...AZUL_CNS_OSCURO);
    doc.setLineWidth(1);
    doc.rect(MARGEN, y, anchoTabla, ALTO_ENCABEZADO);
    y += ALTO_ENCABEZADO;
    doc.setLineWidth(0.5);
  }

  function dibujarTextoAlineado(texto, x, yPos, ancho, align) {
    if (align === 'center') {
      doc.text(texto, x + ancho / 2, yPos, { align: 'center' });
    } else {
      doc.text(texto, x + PAD_X, yPos);
    }
  }

  function nuevaPaginaSiHaceFalta(alturaNecesaria) {
    if (y + alturaNecesaria > altoPagina - MARGEN) {
      doc.addPage();
      y = MARGEN;
      dibujarEncabezadoTabla();
    }
  }

  function calcularAltoFila(fila) {
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    let maxLineas = 1;
    ['nombre', 'puesto', 'motivo'].forEach(key => {
      const col = COLUMNAS.find(c => c.key === key);
      const lineas = doc.splitTextToSize(String(fila[key] || ''), col.width - PAD_X * 2);
      maxLineas = Math.max(maxLineas, lineas.length);
    });
    const altoTexto = PAD_Y * 2 + maxLineas * ALTO_LINEA_TEXTO;
    const altoFirma = PAD_Y * 2 + ALTO_LINEA_TEXTO + ALTO_FIRMA_MINI;
    return Math.max(ALTO_MIN_FILA, altoTexto, altoFirma);
  }

  function dibujarFirmaMini(dataUrl, etiqueta, x, yTope, ancho) {
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(6);
    doc.setTextColor(110);
    doc.text(etiqueta, x + ancho / 2, yTope, { align: 'center' });
    doc.setTextColor(0);
    const xImg = x + (ancho - ANCHO_FIRMA_MINI) / 2;
    const yImg = yTope + 2;
    doc.setDrawColor(190);
    doc.rect(xImg, yImg, ANCHO_FIRMA_MINI, ALTO_FIRMA_MINI);
    if (dataUrl) {
      try {
        doc.addImage(dataUrl, 'PNG', xImg + 1, yImg + 1, ANCHO_FIRMA_MINI - 2, ALTO_FIRMA_MINI - 2, undefined, 'FAST');
      } catch { /* imagen corrupta: se deja el recuadro vacío */ }
    }
  }

  function dibujarFila(fila, indice) {
    const altoFila = calcularAltoFila(fila);
    nuevaPaginaSiHaceFalta(altoFila);

    const yFila = y;

    // Franja muy clara en cada renglón alterno (mismo tono que el azul
    // del membrete, muy aclarado) para que la tabla se lea como un bloque
    // y no como filas sueltas — color sólido en vez de opacidad, para que
    // se vea igual en cualquier navegador.
    if (indice % 2 === 1) {
      doc.setFillColor(236, 238, 247);
      doc.rect(MARGEN, yFila, anchoTabla, altoFila, 'F');
    }

    doc.setDrawColor(180);

    COLUMNAS.forEach((col, i) => {
      const x = columnasX[i];

      if (col.key === 'firma') {
        const anchoSub = (col.width - PAD_X * 2 - 4) / 2;
        const xEntrada = x + PAD_X;
        const xSalida = xEntrada + anchoSub + 4;
        const yTope = yFila + PAD_Y;
        dibujarFirmaMini(fila.firmaEntrada, 'Entrada', xEntrada, yTope, anchoSub);
        dibujarFirmaMini(fila.firmaSalida, 'Salida', xSalida, yTope, anchoSub);
      } else {
        doc.setFont('helvetica', col.key === 'no' ? 'bold' : 'normal');
        doc.setFontSize(8);
        if (col.key === 'no') doc.setTextColor(...AZUL_CNS_OSCURO); else doc.setTextColor(0);
        const lineas = doc.splitTextToSize(String(fila[col.key] || ''), col.width - PAD_X * 2);
        let ly = yFila + PAD_Y + ALTO_LINEA_TEXTO - 2;
        lineas.forEach(linea => {
          dibujarTextoAlineado(linea, x, ly, col.width, col.align);
          ly += ALTO_LINEA_TEXTO;
        });
      }

      if (i > 0) doc.line(x, yFila, x, yFila + altoFila);
    });

    doc.setTextColor(0);
    doc.setDrawColor(180);
    doc.rect(MARGEN, yFila, anchoTabla, altoFila);
    y += altoFila;
  }

  dibujarEncabezadoDocumento();

  const filas = aplanarFilas(agruparPorFolio(rows));

  if (filas.length === 0) {
    dibujarEncabezadoTabla();
    doc.setFont('helvetica', 'italic');
    doc.setFontSize(10);
    doc.setTextColor(90);
    doc.text('No hay registros para estos filtros.', MARGEN + PAD_X, y + 18);
    doc.setTextColor(0);
  } else {
    dibujarEncabezadoTabla();
    filas.forEach((fila, i) => dibujarFila(fila, i));
  }

  const fechaArchivo = new Date().toISOString().slice(0, 10);
  doc.save(`bitacora_cinoteca_${fechaArchivo}.pdf`);
}
